create or replace function public.market_conversations() returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.market_account(); begin return coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (select c.*,(select p.brief->>'title' from private.market_projects p where p.id=c.project_id) as project_title,coalesce((select p.data->>'name' from private.talent_owners o join public.talent_profiles p on p.id=o.profile_id where o.user_id=case when c.initiator_id=u then c.recipient_id else c.initiator_id end limit 1),'Member') as counterpart_name,(select count(*) from private.market_messages m where m.conversation_id=c.id and m.sender_id<>u and (m.created_at,m.id)>(coalesce((select r.read_at from private.market_read_positions r where r.conversation_id=c.id and r.user_id=u),'-infinity'),coalesce((select r.read_message_id from private.market_read_positions r where r.conversation_id=c.id and r.user_id=u),'00000000-0000-0000-0000-000000000000'::uuid))) as unread_count,(select m.body from private.market_messages m where m.conversation_id=c.id order by m.created_at desc limit 1) as last_body from private.market_conversations c where u in(c.initiator_id,c.recipient_id)) q),'[]'); end $$;
create or replace function public.market_thread(conversation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare c private.market_conversations:=private.market_conversation_access(conversation_id); begin return jsonb_build_object('conversation',to_jsonb(c)||jsonb_build_object('project_title',(select p.brief->>'title' from private.market_projects p where p.id=c.project_id),'counterpart_name',coalesce((select p.data->>'name' from private.talent_owners o join public.talent_profiles p on p.id=o.profile_id where o.user_id=case when c.initiator_id=auth.uid() then c.recipient_id else c.initiator_id end limit 1),'Member')),'messages',coalesce((select jsonb_agg(to_jsonb(m) order by m.created_at,m.id) from private.market_messages m where m.conversation_id=c.id),'[]'),'attachments',coalesce((select jsonb_agg(to_jsonb(a)-'object_path' order by a.created_at) from private.market_attachments a where a.conversation_id=c.id),'[]')); end $$;
